'use strict';
/**
 * Export / import of boards and whole games as a single ".gdboard" file (JSON).
 *
 * SECURITY: an import file comes from another person and is treated as hostile.
 *  - Nothing from the file is copied through as-is. Every item is rebuilt field by
 *    field from an allow-list, with type checks and size limits.
 *  - Note HTML is re-generated by a strict allow-list sanitizer (no scripts, event
 *    handlers, links, iframes, SVG, url() in CSS, etc.).
 *  - Images are only accepted if their bytes are a real raster image (PNG, JPEG, GIF,
 *    WebP, BMP — never SVG). The caller can re-encode them (the app does, via Electron).
 *  - File names inside the export are never used on disk: images get fresh random
 *    names and game/board names go through sanitizeName, so no path traversal.
 *  - The file itself is plain data (JSON); nothing in it is ever executed.
 *
 * Dependency-free plain Node (shared with the stdio MCP server bundle).
 */
const { newId, sanitizeName, imageSize, normalizeStyle } = require('./store');

const FORMAT = 'game-dev-board-export';
const FORMAT_VERSION = 1;
const FILE_EXT = 'gdboard';

const LIMITS = {
  fileBytes: 1024 * 1024 * 1024, // 1 GB
  boards: 500,
  itemsPerBoard: 20000,
  imageBytes: 64 * 1024 * 1024,
  htmlChars: 300000,
  textChars: 200000,
  captionChars: 1000,
  points: 50000,
  coord: 1e7,
  nameChars: 120,
};

// ======================= HTML sanitizer =======================
const ALLOWED_TAGS = new Set(['div', 'p', 'br', 'b', 'strong', 'i', 'em', 'u', 's', 'strike', 'del', 'span', 'font', 'code', 'pre', 'ul', 'ol', 'li', 'h1', 'h2', 'h3', 'h4', 'blockquote', 'sub', 'sup', 'hr']);
const VOID_TAGS = new Set(['br', 'hr']);
// Elements whose *content* must be dropped too, not just the tags.
const DROP_CONTENT = new Set(['script', 'style', 'iframe', 'object', 'embed', 'svg', 'math', 'template', 'noscript', 'textarea', 'select', 'title', 'head', 'frameset', 'frame', 'applet', 'xml', 'noembed', 'noframes', 'plaintext', 'xmp', 'canvas', 'video', 'audio']);
const ALLOWED_CSS = new Set(['color', 'background-color', 'font-size', 'font-family', 'font-weight', 'font-style', 'text-decoration', 'text-decoration-line', 'text-align']);

const COLOR_RE = /^(#[0-9a-f]{3,8}|rgba?\(\s*[\d.]+%?\s*,\s*[\d.]+%?\s*,\s*[\d.]+%?\s*(,\s*[\d.]+%?\s*)?\)|[a-z]{3,20})$/i;
const NOTE_NAMES = new Set(['yellow', 'tan', 'green', 'blue', 'pink', 'purple', 'gray']);

function safeColor(v) {
  if (typeof v !== 'string') return null;
  const s = v.trim();
  if (s.length > 40 || !COLOR_RE.test(s)) return null;
  if (/^(expression|url|inherit|initial|unset|revert|var)$/i.test(s)) return null;
  return s;
}

function safeFontFamily(v) {
  if (typeof v !== 'string') return null;
  const s = v.replace(/["']/g, '').trim();
  return /^[\w ,\-]{1,80}$/.test(s) ? s : null;
}

function cssValueOk(prop, value) {
  const v = value.trim();
  if (!v || v.length > 80) return false;
  if (/[\\<>{}();]|url|expression|javascript|@import|attr\s*\(|var\s*\(/i.test(v.replace(/^rgba?\([\d\s.,%]+\)$/i, ''))) return false;
  switch (prop) {
    case 'color':
    case 'background-color': return !!safeColor(v);
    case 'font-size': return /^(\d{1,3}(\.\d+)?(px|em|rem|%|pt)|xx?-small|small|medium|large|xx?x?-large|smaller|larger)$/i.test(v);
    case 'font-family': return !!safeFontFamily(v);
    case 'font-weight': return /^(normal|bold|bolder|lighter|[1-9]00)$/i.test(v);
    case 'font-style': return /^(normal|italic|oblique)$/i.test(v);
    case 'text-decoration':
    case 'text-decoration-line': return /^(none|underline|line-through|overline)( (underline|line-through|overline))*$/i.test(v);
    case 'text-align': return /^(left|right|center|justify|start|end)$/i.test(v);
    default: return false;
  }
}

function sanitizeStyleAttr(style) {
  const out = [];
  for (const decl of String(style).split(';')) {
    const idx = decl.indexOf(':');
    if (idx < 0) continue;
    const prop = decl.slice(0, idx).trim().toLowerCase();
    const value = decl.slice(idx + 1).trim();
    if (ALLOWED_CSS.has(prop) && cssValueOk(prop, value)) out.push(`${prop}: ${value.replace(/["']/g, '')}`);
  }
  return out.join('; ');
}

const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', '#39': "'" };
function decodeEntities(s) {
  return s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+\d*);/gi, (m, e) => {
    const k = e.toLowerCase();
    if (ENT[k] !== undefined) return ENT[k];
    if (k[0] === '#') {
      const code = k[1] === 'x' ? parseInt(k.slice(2), 16) : parseInt(k.slice(1), 10);
      if (Number.isFinite(code) && code > 0 && code < 0x110000 && !(code >= 0xd800 && code <= 0xdfff)) return String.fromCodePoint(code);
      return '';
    }
    return m;
  });
}
function escapeText(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/ /g, '&nbsp;');
}
function escapeAttr(s) {
  return s.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function parseAttrs(src) {
  const attrs = {};
  const re = /([^\s"'<>/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;
  let m;
  while ((m = re.exec(src))) {
    const name = m[1].toLowerCase();
    if (name in attrs) continue;
    attrs[name] = decodeEntities(m[2] ?? m[3] ?? m[4] ?? '');
  }
  return attrs;
}

/**
 * Allow-list HTML sanitizer. Output is rebuilt from scratch: only allowed tags, only
 * "style" (filtered) plus <font face/color/size>; text is re-escaped.
 */
function sanitizeHtml(input) {
  const html = String(input || '').slice(0, LIMITS.htmlChars);
  let out = '';
  const stack = [];
  let dropDepth = 0;
  let dropTag = null;
  const re = /<!--[\s\S]*?(?:-->|$)|<!\[CDATA\[[\s\S]*?(?:\]\]>|$)|<![^>]*>?|<\?[^>]*>?|<(\/?)([a-zA-Z][a-zA-Z0-9-]*)((?:[^>"']|"[^"]*"|'[^']*')*)(\/?)>|([^<]+)|(<)/g;
  let m;
  while ((m = re.exec(html))) {
    const [, slash, rawTag, rawAttrs, , text, lt] = m;
    if (text !== undefined || lt !== undefined) {
      if (!dropDepth) out += escapeText(decodeEntities(text !== undefined ? text : '<'));
      continue;
    }
    if (!rawTag) continue; // comment, CDATA, doctype, processing instruction
    const tag = rawTag.toLowerCase();
    if (dropDepth) {
      if (tag === dropTag) dropDepth += slash ? -1 : 1;
      continue;
    }
    if (DROP_CONTENT.has(tag)) {
      if (!slash) { dropDepth = 1; dropTag = tag; }
      continue;
    }
    if (!ALLOWED_TAGS.has(tag)) continue; // drop the tag, keep its text
    if (slash) {
      const idx = stack.lastIndexOf(tag);
      if (idx >= 0) {
        while (stack.length > idx) out += `</${stack.pop()}>`;
      }
      continue;
    }
    const attrs = parseAttrs(rawAttrs || '');
    const kept = [];
    if (attrs.style) {
      const st = sanitizeStyleAttr(attrs.style);
      if (st) kept.push(`style="${escapeAttr(st)}"`);
    }
    if (tag === 'font') {
      const c = safeColor(attrs.color);
      if (c) kept.push(`color="${escapeAttr(c)}"`);
      const f = safeFontFamily(attrs.face);
      if (f) kept.push(`face="${escapeAttr(f)}"`);
      if (/^[1-7]$/.test(attrs.size || '')) kept.push(`size="${attrs.size}"`);
    }
    out += `<${tag}${kept.length ? ` ${kept.join(' ')}` : ''}>`;
    if (!VOID_TAGS.has(tag)) {
      if (stack.length > 64) { out = out.slice(0, out.lastIndexOf('<')); continue; } // absurd nesting
      stack.push(tag);
    }
  }
  while (stack.length) out += `</${stack.pop()}>`;
  return out;
}

// ======================= item validation =======================
const num = (v, def = 0, min = -LIMITS.coord, max = LIMITS.coord) => {
  const n = Number(v);
  return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : def;
};
const str = (v, max) => (typeof v === 'string' ? v.slice(0, max) : '');
const isoDate = (v) => (typeof v === 'string' && v.length < 40 && !Number.isNaN(Date.parse(v)) ? new Date(v).toISOString() : new Date().toISOString());

function cleanTextStyle(st) {
  if (!st || typeof st !== 'object' || Array.isArray(st)) return {};
  const pick = {
    fontFamily: safeFontFamily(st.fontFamily) || undefined,
    fontSize: st.fontSize,
    color: safeColor(st.color) || undefined,
    background: NOTE_NAMES.has(st.background) ? st.background : (safeColor(st.background) || undefined),
    bold: st.bold === true || undefined,
    italic: st.italic === true || undefined,
    underline: st.underline === true || undefined,
    strike: st.strike === true || undefined,
    align: st.align,
  };
  return normalizeStyle(pick);
}

function cleanDrawStyle(st) {
  const s = st && typeof st === 'object' && !Array.isArray(st) ? st : {};
  const out = {
    color: s.color === 'ink' ? 'ink' : (safeColor(s.color) || '#e03131'),
    width: num(s.width, 4, 0.5, 120),
  };
  if (s.dash === true) out.dash = true;
  if (s.opacity !== undefined) out.opacity = num(s.opacity, 1, 0.05, 1);
  return out;
}

const DRAW_KINDS = new Set(['pen', 'highlighter', 'line', 'arrow', 'rect', 'ellipse']);

/** Rebuild one item from untrusted input. Returns null if it is not acceptable. */
function cleanItem(raw, imageSrcs) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
  const base = {
    x: num(raw.x), y: num(raw.y),
    w: num(raw.w, 1, 0, LIMITS.coord), h: num(raw.h, 0, 0, LIMITS.coord),
    z: Math.round(num(raw.z, 0, -1e6, 1e6)),
    author: raw.author === 'claude' ? 'claude' : 'user',
    createdAt: isoDate(raw.createdAt),
    updatedAt: isoDate(raw.updatedAt),
  };
  if (raw.type === 'text') {
    const html = sanitizeHtml(raw.html);
    return {
      id: newId('txt'), type: 'text', ...base, w: Math.max(40, base.w || 320),
      html, text: str(raw.text, LIMITS.textChars), style: cleanTextStyle(raw.style),
    };
  }
  if (raw.type === 'image') {
    if (typeof raw.src !== 'string' || !imageSrcs.has(raw.src)) return null;
    const it = {
      id: newId('img'), type: 'image', ...base, w: Math.max(4, base.w), h: Math.max(4, base.h || base.w),
      src: raw.src, // remapped to a fresh file name on import
    };
    if (Number.isFinite(Number(raw.naturalWidth))) it.naturalWidth = Math.round(num(raw.naturalWidth, 0, 0, 100000));
    if (Number.isFinite(Number(raw.naturalHeight))) it.naturalHeight = Math.round(num(raw.naturalHeight, 0, 0, 100000));
    const cap = str(raw.caption, LIMITS.captionChars).trim();
    if (cap) it.caption = cap;
    return it;
  }
  if (raw.type === 'draw') {
    if (!DRAW_KINDS.has(raw.kind)) return null;
    const pts = Array.isArray(raw.points) ? raw.points.slice(0, LIMITS.points) : [];
    const points = [];
    for (const p of pts) {
      if (!Array.isArray(p) || p.length < 2) continue;
      points.push([num(p[0]), num(p[1])]);
    }
    if ((raw.kind === 'line' || raw.kind === 'arrow') && points.length !== 2) return null;
    if ((raw.kind === 'pen' || raw.kind === 'highlighter') && !points.length) return null;
    return {
      id: newId('drw'), type: 'draw', kind: raw.kind, ...base, w: Math.max(1, base.w), h: Math.max(1, base.h),
      points: raw.kind === 'rect' || raw.kind === 'ellipse' ? [] : points,
      style: cleanDrawStyle(raw.style),
    };
  }
  return null; // unknown item type
}

// ======================= export =======================
function exportData(store, game, boardNames, appVersion) {
  const gameName = require('path').basename(store.gameDir(game));
  const names = boardNames || store.listBoards(gameName).map((b) => b.name);
  const boards = [];
  for (const name of names) {
    const data = store.readBoard(gameName, name);
    const images = {};
    for (const it of data.items) {
      if (it.type !== 'image' || images[it.src]) continue;
      try {
        const img = store.readImage(gameName, data.name, it.src);
        images[it.src] = { mime: img.mime, data: img.buffer.toString('base64') };
      } catch { /* missing image file: skip it */ }
    }
    boards.push({ name: data.name, items: data.items, images });
  }
  return {
    format: FORMAT,
    formatVersion: FORMAT_VERSION,
    kind: boardNames && boardNames.length === 1 ? 'board' : 'game',
    appVersion: appVersion || null,
    exportedAt: new Date().toISOString(),
    game: gameName,
    boards,
  };
}

function exportToBuffer(store, game, boardNames, appVersion) {
  return Buffer.from(JSON.stringify(exportData(store, game, boardNames, appVersion)), 'utf8');
}

// ======================= import: parse + validate =======================
/**
 * Parse and validate an export file. Throws on anything that isn't a valid export.
 * @param {Buffer|string} input
 * @param {(buf:Buffer, info:{ext:string,mime:string}) => Buffer|null} [reencode] optional image re-encoder
 */
function parseExport(input, reencode) {
  const buf = Buffer.isBuffer(input) ? input : Buffer.from(String(input), 'utf8');
  if (buf.length > LIMITS.fileBytes) throw new Error('File is too large to import');
  let raw;
  try {
    raw = JSON.parse(buf.toString('utf8'));
  } catch {
    throw new Error('This is not a Game Development Board export (could not read it as JSON)');
  }
  if (!raw || typeof raw !== 'object' || raw.format !== FORMAT) throw new Error('This is not a Game Development Board export file');
  if (typeof raw.formatVersion !== 'number' || raw.formatVersion > FORMAT_VERSION) {
    throw new Error('This export was made by a newer version of the app. Update the app (Check for updates), then try again.');
  }
  if (!Array.isArray(raw.boards) || !raw.boards.length) throw new Error('The export contains no boards');
  if (raw.boards.length > LIMITS.boards) throw new Error('The export contains too many boards');

  const warnings = [];
  const game = sanitizeName(str(raw.game, LIMITS.nameChars) || 'Imported game');
  const boards = [];
  let imageCount = 0;
  let itemCount = 0;
  for (const rb of raw.boards) {
    if (!rb || typeof rb !== 'object') continue;
    let name;
    try { name = sanitizeName(str(rb.name, LIMITS.nameChars)); } catch { name = 'Imported board'; }
    // Validate images first (by content, never by the file name or claimed type).
    const images = new Map();
    const rawImages = rb.images && typeof rb.images === 'object' && !Array.isArray(rb.images) ? rb.images : {};
    for (const src of Object.keys(rawImages)) {
      const entry = rawImages[src];
      if (typeof src !== 'string' || src.length > 300 || !entry || typeof entry.data !== 'string') continue;
      if (entry.data.length > LIMITS.imageBytes * 1.4) { warnings.push(`Skipped an oversized image in "${name}"`); continue; }
      if (!/^[A-Za-z0-9+/=\s]*$/.test(entry.data)) { warnings.push(`Skipped an invalid image in "${name}"`); continue; }
      let bytes = Buffer.from(entry.data, 'base64');
      const info = imageSize(bytes);
      if (!info || !info.width || !info.height || info.width > 30000 || info.height > 30000) {
        warnings.push(`Skipped a file in "${name}" that is not a supported image`);
        continue;
      }
      if (reencode) {
        const re = reencode(bytes, info);
        if (re === null) { warnings.push(`Skipped an image in "${name}" that could not be decoded`); continue; }
        if (re) bytes = re;
      }
      images.set(src, { bytes, mime: info.mime });
    }
    const rawItems = Array.isArray(rb.items) ? rb.items.slice(0, LIMITS.itemsPerBoard) : [];
    if (Array.isArray(rb.items) && rb.items.length > LIMITS.itemsPerBoard) warnings.push(`"${name}" had too many items; some were skipped`);
    const items = [];
    let dropped = 0;
    for (const ri of rawItems) {
      const it = cleanItem(ri, images);
      if (it) items.push(it); else dropped++;
    }
    if (dropped) warnings.push(`Skipped ${dropped} unsupported item${dropped > 1 ? 's' : ''} in "${name}"`);
    // Only keep images that an item actually uses.
    const used = new Set(items.filter((i) => i.type === 'image').map((i) => i.src));
    for (const k of [...images.keys()]) if (!used.has(k)) images.delete(k);
    imageCount += images.size;
    itemCount += items.length;
    boards.push({ name, items, images });
  }
  if (!boards.length) throw new Error('The export contains no valid boards');
  return {
    kind: raw.kind === 'board' ? 'board' : 'game',
    game,
    appVersion: str(raw.appVersion, 30) || null,
    exportedAt: typeof raw.exportedAt === 'string' && !Number.isNaN(Date.parse(raw.exportedAt)) ? new Date(raw.exportedAt).toISOString() : null,
    boards,
    imageCount,
    itemCount,
    warnings,
  };
}

function uniqueName(existing, base) {
  const lower = new Set(existing.map((n) => n.toLowerCase()));
  if (!lower.has(base.toLowerCase())) return base;
  for (let i = 2; i < 1000; i++) {
    const cand = `${base} (${i})`;
    if (!lower.has(cand.toLowerCase())) return cand;
  }
  return `${base} ${Date.now()}`;
}

/**
 * Write a parsed (already validated) export into the store.
 * @param {object} opts
 * @param {string} [opts.targetGame] existing game to merge into; otherwise a new game is created
 * @param {string} [opts.newGameName] name for a new game (made unique if taken)
 */
function importParsed(store, parsed, opts = {}) {
  let gameName;
  if (opts.targetGame) {
    gameName = require('path').basename(store.gameDir(opts.targetGame)); // throws if missing
  } else {
    const wanted = sanitizeName(opts.newGameName || parsed.game);
    gameName = uniqueName(store.listGames().map((g) => g.name), wanted);
    store.createGame(gameName);
  }
  const created = [];
  for (const b of parsed.boards) {
    const boardName = uniqueName(store.listBoards(gameName).map((x) => x.name), b.name);
    store.createBoard(gameName, boardName);
    const srcMap = new Map();
    for (const [oldSrc, img] of b.images) {
      const saved = store.saveImage(gameName, boardName, img.bytes, img.mime);
      srcMap.set(oldSrc, saved.src);
    }
    const items = [];
    for (const it of b.items) {
      if (it.type === 'image') {
        const src = srcMap.get(it.src);
        if (!src) continue;
        items.push({ ...it, src });
      } else {
        items.push(it);
      }
    }
    store.applyPatch(gameName, boardName, { upserts: items }, 'import');
    created.push(boardName);
  }
  return { game: gameName, boards: created };
}

module.exports = {
  FORMAT, FORMAT_VERSION, FILE_EXT, LIMITS,
  sanitizeHtml, cleanItem, exportData, exportToBuffer, parseExport, importParsed, uniqueName,
};
